import{_ as n,C as s,o as l,c as u,j as o,E as a,w as r,a as t,a3 as d}from"./chunks/framework.DiHTnZWQ.js";const B=JSON.parse('{"title":"大海","description":"","frontmatter":{},"headers":[],"relativePath":"Break/Journal2.md","filePath":"Break/Journal2.md","lastUpdated":1787210058000}'),_={name:"Break/Journal2.md"},i={id:"大海",tabindex:"-1"};function m(q,p,f,c,T,k){const e=s("center");return l(),u("div",null,[o("h1",i,[a(e,null,{default:r(()=>[...p[0]||(p[0]=[t("大海",-1)])]),_:1}),p[1]||(p[1]=t()),p[2]||(p[2]=o("a",{class:"header-anchor",href:"#大海","aria-label":'Permalink to "<center>大海</center>"'},"​",-1))]),a(e,null,{default:r(()=>[...p[3]||(p[3]=[t("2026.8.20",-1)])]),_:1}),p[4]||(p[4]=d("<p>这场激素的瘟疫比想象中的来得更快。</p><p>快到……一个从珠峰上滚下的偌大雪球，攥住了所有多巴胺的关口。</p><p>吞掉那根黑色的长头发，预想中的死亡并没有到来。</p><p>毕竟，一根头发，怎么也不可能塞满整个气管，怎么也不能扼住命运的咽喉。</p><p>那么，倘若是十根、一百根、一千根……</p><p>故事里，那条蓝色的燕鱼，叫吧嗒。他来自充满自由的大海，他说那里无边无垠，他说那里深不见底，他说那里是没有禁锢的国度。望着四处透明的玻璃，他着了魔，也发了疯，他一次又一次地给予这些所谓的“束缚”以猛烈的撞击，但没有鱼劝他停下。他们心里长着一块明镜，是盖子底下的那只暴烈的比目鱼老崔种下的种子……</p><p>——“你们什么都不用做，食客来了，装死就可以了。”</p><p>老崔没有见过真正的大海，但他最爱的她见过。老崔的女友正来自吧嗒说的那片美丽的地方。无数个星星点灯的夜里，她和老崔说起大海的种种，说希望他和自己都能努力地活下去，活到挣脱鱼缸的那一天，活到不惜一切代价跳进大海的那一天。</p><p>没听错，Whatever It Takes，不惜一切代价。</p><p>至于装死的种子，是老崔的女友埋在他心底最柔软的地方，他视若珍宝。</p><p>月黑风高的晚上，食客点名要吃比目鱼，那条躺在底层、一动不动的比目鱼。</p><p>那是老崔的女友。</p><p>老崔翻着肚皮，看着她被粗暴地抓了出去，看着她临终前的眼神——那不是对死亡的恐惧，而是对他的深深遗憾。</p><p>她在说：活下去。</p><p>但吧嗒看见了。那条年轻的蓝色燕鱼，用他所有的绝望和愤怒，向玻璃发起了最后的冲锋。</p><p>&quot;住手！&quot;老崔冲了过来，用他略显苍老的身躯挡在吧嗒面前，&quot;装死！你听我说，装死就能活！&quot;</p><p>吧嗒没有停下。他的眼睛已经看不到老崔了，他只看到了被提起来的老崔的她，看到了刀子，看到了所有的绝望都在此刻汇聚成一团烈火。</p><p>&quot;不。&quot;吧嗒低声说，&quot;我不会再装死了。&quot;</p><p>他转身冲向老崔，两条鱼在水草之间扭打成一团。老崔想要压制住他，但他已经疯了，疯得比任何时刻都更彻底。鳍划破了皮肤，鳞片飘落下来，红色的血迹在水中晕开。吧嗒负了伤，伤得很重，但他的眼神中没有半分退缩。</p><p>&quot;让开。&quot;吧嗒喘着气说。</p><p>老崔退开了。他看到了吧嗒眼睛里的决绝，就像曾经在她眼里看到的那样。</p><p>吧嗒赌气一般，用最后的力气冲向水面。他要跳出去，他要逃离这个地狱。短暂的自由时刻，他感受到了空气，感受到了不一样的世界。</p><p>但手很快就来了。粗糙、冰冷、无情的手。</p><p>他被抓了回来。</p><p>身上的水迹未干，食客就走了进来。吧嗒还躺在网子里，还在不断地挣扎。食客看到了他——看到了这条受伤的、疯狂的蓝色燕鱼。</p><p>&quot;就这条。&quot;</p><p>老崔看见了一切。当刀落下的那一刻，他的心也碎了。他看着吧嗒的眼睛在逐渐黯淡，看着那个曾经充满对大海向往的灵魂，就这样被困死在了一个鱼缸里。</p><p>不是因为鱼缸。是因为选择——是因为大海。</p><p>悲愤交加的老崔动了。他不再装死，不再沉默。他冲出了鱼缸，跳得很高、很远，高到超过了网子的范围，远到食客根本没来得及反应。</p><p>他落进了外面的水里——一片广阔的、流动的、似乎无边无垠的水面。老崔没有多想，只是本能地游向远方。玻璃的束缚消失了，小小的鱼缸消失了，那些虚伪的装死也消失了。</p><p>他游了很久很久，直到终于到达了一片看起来像是大海的地方。</p><p>但老崔没有看清。</p><p>他不明白，自己游进的不是大海，而是一个巨大的鱼塘——被鱼老板用防护网圈起来的鱼塘。网子在水下，在看不见的地方。而他的她，永远也不会知道，他们向往的天堂，早就被这个世界标了价。</p><p>就像那些激素一样，就像那条黑色的长头发一样。激素有流失就会有一点，有一些，有一片，头发有一根就会有十根，会有一百根，会有一千根。</p><p>这场瘟疫来源于恨，终极的痛恨。</p><p>曾以为，死亡应该是一件轰轰烈烈的事情，后来才发现不是，更像是一场很长很长的冬天。</p><p>雪落下来、覆盖脚印、覆盖窗台、覆盖那些没有说出口的话、覆盖一个人曾经热烈地爱过、喜欢过、期待过的一生。</p><p>曾想过，要不要再走几步，后来却也没有。不是因为突然想通了什么，也不是因为这个世界忽然变得值得留恋。</p><p>——只是太累了。</p><p>累到连悲伤都需要耗费力气。</p><p>所以开始一点一点地把自己从这个操蛋的世界上撤走。</p><p>慢慢地恐惧明天，恐惧今天，恐惧睁眼的一瞬间。窗帘缝里漏进来的阳光，明明和从前一样温柔，却再也照不进身体，更照不进心里。</p><p>——相反，只有漫无边际的恐惧。</p><p>十五岁的 dht，谢谢你，谢谢你在那个热烈的盛夏追逐自己想要的一切……但十九岁的你搞砸了所有的未来，二十岁的你等不到春暖花开了——我想，提前离开一个世界，提前认识一个世界。我还想……找回自己失散多年的灵魂。</p><p>这场瘟疫从未真正地夺走生命，何况那根无关痛痒的头发。只是走了很久，久到不知道自己在追逐着什么，走到自己终于背负了所有以爱为名的恨，走到……此生未见的雷霆万钧。</p><p>只是2023年的雪球，如果没有滚下来呢……</p><p>算了，反正也晚了。</p><p>哈哈哈哈！</p><p>你好！</p><p>谢谢你！</p><p>再见！</p><p>祝你幸福~</p><p>晚安……</p>",53))])}const N=n(_,[["render",m]]);export{B as __pageData,N as default};
